CREATE OR REPLACE FUNCTION public.icash_reserve_and_claim_filtered_discovery(p_account uuid, p_zip text, p_revision uuid, p_page integer, p_per_page integer, p_rate uuid, p_unit bigint, p_permission_until timestamp with time zone, p_setup_revision integer, p_market_mode text, p_market text, p_plan jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare op text:='discovery:'||p_account||':'||p_revision||':'||p_page;
begin
 if not public.icash_discovery_filter_plan_valid(p_plan) then return false;end if;
 -- The original admission function retains every budget, permission and scope gate.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 perform 1 from public.icash_discovery_configs where account_id=p_account for update;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled)
 or exists(select 1 from public.icash_discovery_filter_pages where operation_key=op) then return false;end if;
 perform 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and zip=p_zip
 and strategy=p_plan->>'strategy' and next_page=(p_plan->>'providerPage')::integer and not exhausted for update;
 if not found then return false;end if;
 if ((select research_version=0 from public.icash_discovery_configs where account_id=p_account) and public.icash_known_assigned_discovery_page(p_zip,p_plan->>'strategy',(p_plan->>'providerPage')::integer,p_per_page) is not null)
 or exists(select 1 from public.icash_discovery_filter_pages fp join public.icash_operation_spend os using(operation_key,account_id)
 join public.icash_discovery_configs dc on dc.account_id=fp.account_id where fp.zip=p_zip and fp.plan->>'strategy'=p_plan->>'strategy'
 and fp.plan->>'providerPage'=p_plan->>'providerPage' and dc.per_page=p_per_page and fp.state='claimed' and os.state not in ('settled','cancelled')) then return false;end if;
 if not public.icash_reserve_and_claim_property_discovery(p_account,p_zip,p_revision,p_page,p_per_page,p_rate,p_unit,p_permission_until,p_setup_revision,p_market_mode,p_market) then return false;end if;
 insert into public.icash_discovery_filter_pages(operation_key,account_id,revision,sequence,zip,plan,state) values(op,p_account,p_revision,p_page,p_zip,p_plan,'claimed');
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_research_discovery(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;ok boolean;op text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if coalesce(c.research_version,0) not in (1,2) or p_policy is distinct from jsonb_build_object('version',case when c.research_version=2 then 'research-efficiency-v2' else 'research-efficiency-v1' end,'exclusionListId',c.research_list_id) then return false;end if;
 if c.research_list_id is not null and exists(select 1 from icash_research_private.exclusion_items where synced_at is null) then return false;end if;
 if p_plan is not null then
  ok:=public.icash_reserve_and_claim_filtered_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market',p_plan);
 else
  ok:=public.icash_reserve_and_claim_property_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market');
 end if;
 if not ok then return false;end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 insert into icash_research_private.query_claims values(op,p_account,p_policy);return true;
end $function$
